class Solution:
    def highestPeak(self, graph: list[list[int]]) -> list[list[int]]:
        rows, cols = len(graph), len(graph[0])
        DIR = [0,1,0,-1,0]
        queue = deque()

        for i in range(rows):
            for j in range(cols):
                if graph[i][j] == 1:
                    queue.append((i, j))
                    graph[i][j] = 0

        seen = set(queue)
        while queue:
            k = len(queue)
            for _ in range(k):
                r, c = queue.popleft()
                for i in range(4):
                    nr, nc = r + DIR[i], c + DIR[i + 1]
                    if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in seen:
                        graph[nr][nc] = graph[r][c] + 1
                        queue.append((nr, nc))
                        seen.add((nr, nc))

        return graph
